from typing import Optional

class BinaryWriter:
    def __init__(self, cache_dir: str):
        self.cache_dir = cache_dir

    def merge(self, num_workers: int = 1, node_rank: Optional[int] = None) -> None:
        index_parts = [f for f in os.listdir(self.cache_dir) if f.startswith("index_part")]

        if node_rank != 0:
            while not os.path.exists(os.path.join(self.cache_dir, "merged_index")):
                time.sleep(1)
            return

        if not index_parts:
            print("No index parts found in the cache directory.")
            return

        while len(index_parts) < num_workers:
            time.sleep(1)
            index_parts = [f for f in os.listdir(self.cache_dir) if f.startswith("index_part")]

        merged_index_path = os.path.join(self.cache_dir, "merged_index")
        if os.path.exists(merged_index_path):
            os.remove(merged_index_path)

        with open(merged_index_path, "wb") as merged_index:
            for part in index_parts:
                with open(os.path.join(self.cache_dir, part), "rb") as index_part:
                    merged_index.write(index_part.read())

        print(f"Merged index file saved at {merged_index_path}")
